+SECURITY_READ_ONLY_EARLY(struct filterops) aio_filtops = {
+	.f_isfd = 0,
+	.f_attach = filt_aioattach,
+	.f_detach = filt_aiodetach,
+	.f_event = filt_aioevent,
+	.f_touch = filt_aiotouch,
+	.f_process = filt_aioprocess,
+};
