+static int
+memorystatus_cmd_rearm_memlimit(pid_t pid, uint32_t flags, __unused int32_t *retval)
+{
+	if (pid == -1) {
+		/* Re-arm all pids */
+		proc_iterate(
+			PROC_ALLPROCLIST,
+			_memstat_rearm_proc_memlimit,
+			&flags,
+			NULL,
+			NULL);
+	} else {
+		/* Re-arm one pid */
+		proc_t p = (pid == proc_selfpid()) ? proc_self() : proc_find(pid);
+		if (!p) {
+			return ESRCH;
+		}
+		_memstat_rearm_proc_memlimit(p, &flags);
+		proc_rele(p);
+	}
+
+	return 0;
+}
