+	case IOPOL_VFS_IGNORE_PERMISSIONS_ON:
+		os_atomic_or(&p->p_vfs_iopolicy, P_VFS_IOPOLICY_IGNORE_NODE_PERMISSIONS, relaxed);
+		break;
+	default:
