+static int sysctl_sptm_sysctl_poke SYSCTL_HANDLER_ARGS
+{
+	int error = 0;
+
+	/* Always read-as-zero. */
+	const uint64_t out = 0;
+	error = SYSCTL_OUT(req, &out, sizeof(out));
+
+	if (error) {
+		return error;
+	}
+
+	uint64_t selector;
+	if (req->newptr) {
+		error = SYSCTL_IN(req, &selector, sizeof(selector));
+		sptm_sysctl(selector, SPTM_SYSCTL_GET, 0);
+	}
+
+	return error;
+}
